rows = query(
    "SELECT t.value AS updated FROM card_values t "
    "WHERE t.entity_type = 'Technology' AND t.field = 'updated' AND "
    "EXISTS (SELECT 1 FROM card_values d, json_each(d.value) j WHERE d.card_id = t.card_id AND d.field = 'domain' AND j.value = ?)",
    (PARAMS["domain"],),
)
counts = {}
for row in rows:
    month = str(row["updated"])[:7]
    counts[month] = counts.get(month, 0) + 1
result = {"columns": ["month", "technologies"],
          "rows": [[m, n] for m, n in sorted(counts.items())]}
